import {useState, useEffect} from 'react';
import {ApiProfessor} from "../api";

const useProfessor = () => {
    const [state, setState] = useState(null);
    useEffect(() => {
        setProfessor();
    },[]);

    const setProfessor = async (professorEndpoint) => {
        if(professorEndpoint != null){
            console.log("endpoint = " + professorEndpoint);
            let professor = await ApiProfessor(professorEndpoint);
            console.log("answer" + JSON.stringify(professor));
            setState(professor.results);
        }

    };
    return [state, setProfessor];
};

export default useProfessor;
